// Extrai, filtra e aleatoriza as melhores ofertas com desconto real
const rawData = $input.first().json;
const results = rawData.results || [];

// Filtra apenas produtos com estoque, imagem válida e desconto real
const ofertasComDesconto = results.filter(item => {
  const precoOriginal = item.original_price || (item.prices && item.prices.prices && item.prices.prices[0] ? item.prices.prices[0].regular_amount : null);
  const precoAtual = item.price;
  return item.title && item.thumbnail && precoAtual > 0 && (precoOriginal > precoAtual || item.installments);
});

if (ofertasComDesconto.length === 0) {
  throw new Error('Nenhuma oferta qualificada encontrada nesta rodada.');
}

// Embaralha aleatoriamente (shuffle) para nunca repetir em sequência
const embaralhado = ofertasComDesconto.sort(() => Math.random() - 0.5);

// Seleciona a melhor oferta da rodada
const selecionado = embaralhado[0];
const precoAtual = Number(selecionado.price);
const precoOriginal = Number(selecionado.original_price) || precoAtual * 1.25;
const descontoPct = precoOriginal > precoAtual ? Math.round(((precoOriginal - precoAtual) / precoOriginal) * 100) : 0;

// Imagem em alta resolução substituindo thumbnail 'I.jpg' por 'O.jpg'
const imagemHd = (selecionado.thumbnail || '').replace('-I.jpg', '-O.jpg').replace('http://', 'https://');

// Parâmetros de Afiliado (substitua pela sua tag/link de afiliado)
const tagAfiliado = $env.AFILIADO_ML_TAG || 'afiliado_gltech';
const linkProduto = selecionado.permalink || '';
const linkComAfiliado = linkProduto.includes('?') ? `${linkProduto}&matt_tool=${tagAfiliado}` : `${linkProduto}?matt_tool=${tagAfiliado}`;

return [{
  json: {
    plataforma: 'Mercado Livre',
    idProduto: selecionado.id,
    titulo: selecionado.title,
    precoOriginal: precoOriginal,
    precoAtual: precoAtual,
    descontoPct: descontoPct,
    imagemUrl: imagemHd,
    linkOriginal: linkProduto,
    linkAfiliado: linkComAfiliado,
    parcelas: selecionado.installments ? `${selecionado.installments.quantity}x de R$ ${selecionado.installments.amount.toFixed(2).replace('.', ',')}` : null,
    dataExtracao: new Date().toISOString()
  }
}];

// Gerador de Copy Persuasiva com Alta Conversão & Gatilhos de Urgência
const item = $input.first().json;

const emojisAlerta = ['🚨 PROMOÇÃO RELÂMPAGO!', '🔥 ACHADINHO IMPERDÍVEL!', '⚡ BAIXOU O PREÇO AGORA!', '💣 SUPER OFERTA DO DIA!'];
const emojiHeader = emojisAlerta[Math.floor(Math.random() * emojisAlerta.length)];

const ctas = [
  '👉 Garanta o seu antes que o estoque acabe:',
  '👉 Toque no link abaixo para aproveitar o desconto:',
  '👉 Clique aqui para resgatar pelo menor preço:',
  '👉 Link oficial com preço promocional:'
];
const ctaTexto = ctas[Math.floor(Math.random() * ctas.length)];

let linhas = [];
linhas.push(`${emojiHeader}\n`);
linhas.push(`📦 *${item.titulo}*\n`);

if (item.precoOriginal > item.precoAtual && item.descontoPct > 0) {
  linhas.push(`❌ De: ~R$ ${item.precoOriginal.toFixed(2).replace('.', ',')}~`);
  linhas.push(`✅ Por apenas: *R$ ${item.precoAtual.toFixed(2).replace('.', ',')}* 🔥 (*${item.descontoPct}% OFF*)`);
} else {
  linhas.push(`✅ Por apenas: *R$ ${item.precoAtual.toFixed(2).replace('.', ',')}* 🔥`);
}

if (item.parcelas) {
  linhas.push(`💳 Em até ${item.parcelas} sem juros!`);
}

linhas.push(`\n${ctaTexto}`);
linhas.push(`🛒 *Link Promocional:* ${item.linkAfiliado}`);
linhas.push('\n⚠️ *Aviso:* Os preços e cupons podem sofrer alteração a qualquer momento pela loja.');
linhas.push('\n#achadinhos #ofertas #desconto');

const copyFormatada = linhas.join('\n');

return [{
  json: {
    ...item,
    copyPronta: copyFormatada
  }
}];

// Configuração dos Grupos do WhatsApp de Destino
// Adicione aqui os IDs/JIDs de todos os grupos para onde deseja enviar
const gruposWhatsApp = [
  "120363414256913914@g.us",
  "120363298471928374@g.us"
];

const itemOferta = $input.first().json;

// Cria um item para cada grupo para rodar o loop com delay
return gruposWhatsApp.map(grupoId => ({
  json: {
    ...itemOferta,
    targetGrupoId: grupoId
  }
}));
